import{_ as r,a0 as a,w as u,s as l,ao as p,I as o,x as s,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"如何在 Ubuntu 中检查你的 IP 地址 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 中检查你的 IP 地址 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 中检查你的 IP 地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 中检查你的 IP 地址 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190823 How To Check Your IP Address in Ubuntu -Beginner-s Tip","title":"如何在 Ubuntu 中检查你的 IP 地址","tag":"201909","desc":""},"relativePath":"201909/20190823 How To Check Your IP Address in Ubuntu -Beginner-s Tip.md","filePath":"[post].md"}'),d={name:"201909/20190823 How To Check Your IP Address in Ubuntu -Beginner-s Tip.md"};function g(b,t,h,f,m,P){const n=a("Link");return u(),l("div",null,[t[23]||(t[23]=p('<h1 id="如何在-ubuntu-中检查你的-ip-地址" tabindex="-1">如何在 Ubuntu 中检查你的 IP 地址 <a class="header-anchor" href="#如何在-ubuntu-中检查你的-ip-地址" aria-label="Permalink to “如何在 Ubuntu 中检查你的 IP 地址”">​</a></h1><p>不知道你的 IP 地址是什么？以下是在 Ubuntu 和其他 Linux 发行版中检查 IP 地址的几种方法。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/checking-ip-address-ubuntu.png?resize=800%2C450&amp;ssl=1" alt=""></p><h3 id="什么是-ip-地址" tabindex="-1">什么是 IP 地址？ <a class="header-anchor" href="#什么是-ip-地址" aria-label="Permalink to “什么是 IP 地址？”">​</a></h3><p><strong>互联网协议地址</strong>（通常称为 <strong>IP 地址</strong>）是分配给连接到计算机网络的每个设备（使用互联网协议）的数字标签。IP 地址用于识别和定位机器。</p><p><strong>IP 地址</strong>在网络中是<em>唯一的</em>，使得所有连接设备能够通信。</p><p>你还应该知道有两种<strong>类型的 IP 地址</strong>：<strong>公有</strong>和<strong>私有</strong>。<strong>公有 IP 地址</strong>是用于互联网通信的地址，这与你用于邮件的物理地址相同。但是，在本地网络（例如使用路由器的家庭）的环境中，会为每个设备分配在该子网内唯一的<strong>私有 IP 地址</strong>。这在本地网络中使用，而不直接暴露公有 IP（路由器用它与互联网通信）。</p><p>另外还有区分 <strong>IPv4</strong> 和 <strong>IPv6</strong> 协议。<strong>IPv4</strong> 是经典的 IP 格式，它由基本的 4 部分结构组成，四个字节用点分隔（例如 127.0.0.1）。但是，随着设备数量的增加，IPv4 很快就无法提供足够的地址。这就是 <strong>IPv6</strong> 被发明的原因，它使用 <strong>128 位地址</strong>的格式（与 <strong>IPv4</strong> 使用的 <strong>32 位地址</strong>相比）。</p><h3 id="在-ubuntu-中检查你的-ip-地址-终端方式" tabindex="-1">在 Ubuntu 中检查你的 IP 地址（终端方式） <a class="header-anchor" href="#在-ubuntu-中检查你的-ip-地址-终端方式" aria-label="Permalink to “在 Ubuntu 中检查你的 IP 地址（终端方式）”">​</a></h3><p>检查 IP 地址的最快和最简单的方法是使用 <code>ip</code> 命令。你可以按以下方式使用此命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip addr show</span></span></code></pre></div><p>它将同时显示 IPv4 和 IPv6 地址：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/ip_addr_show.png?fit=800%2C493&amp;ssl=1" alt="Display IP Address in Ubuntu Linux"></p><p>实际上，你可以进一步缩短这个命令 <code>ip a</code>。它会给你完全相同的结果。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ip a</span></span></code></pre></div><p>如果你希望获得最少的细节，也可以使用 <code>hostname</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hostname -I</span></span></code></pre></div>',17)),o("p",null,[t[1]||(t[1]=s("还有一些",-1)),i(n,{href:"https://linuxhandbook.com/find-ip-address/"},{default:e(()=>[...t[0]||(t[0]=[s("在 Linux 中检查 IP 地址的方法",-1)])]),_:1}),t[2]||(t[2]=s("，但是这两个命令足以满足这个目的。",-1))]),t[24]||(t[24]=p('<p><code>ifconfig</code> 如何？</p><p>老用户可能会想要使用 <code>ifconfig</code>（net-tools 软件包的一部分），但该程序已被弃用。一些较新的 Linux 发行版不再包含此软件包，如果你尝试运行它，你将看到 ifconfig 命令未找到的错误。</p><h3 id="在-ubuntu-中检查你的-ip-地址-gui-方式" tabindex="-1">在 Ubuntu 中检查你的 IP 地址（GUI 方式） <a class="header-anchor" href="#在-ubuntu-中检查你的-ip-地址-gui-方式" aria-label="Permalink to “在 Ubuntu 中检查你的 IP 地址（GUI 方式）”">​</a></h3><p>如果你对命令行不熟悉，你还可以使用图形方式检查 IP 地址。</p><p>打开 Ubuntu 应用菜单（在屏幕左下角<strong>显示应用</strong>）并搜索<strong>Settings</strong>，然后单击图标：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/08/applications_menu_settings.jpg?fit=800%2C309&amp;ssl=1" alt="Applications Menu Settings"></p><p>这应该会打开<strong>设置菜单</strong>。进入<strong>网络</strong>：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/network_settings_ubuntu.jpg?fit=800%2C591&amp;ssl=1" alt="Network Settings Ubuntu"></p><p>按下连接旁边的<strong>齿轮图标</strong>会打开一个窗口，其中包含更多设置和有关你网络链接的信息，其中包括你的 IP 地址：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/08/ip_address_gui_ubuntu.png?fit=800%2C510&amp;ssl=1" alt="IP Address GUI Ubuntu"></p><h3 id="额外提示-检查你的公共-ip-地址-适用于台式计算机" tabindex="-1">额外提示：检查你的公共 IP 地址（适用于台式计算机） <a class="header-anchor" href="#额外提示-检查你的公共-ip-地址-适用于台式计算机" aria-label="Permalink to “额外提示：检查你的公共 IP 地址（适用于台式计算机）”">​</a></h3>',11)),o("p",null,[t[4]||(t[4]=s("首先，要检查你的",-1)),t[5]||(t[5]=o("strong",null,"公有 IP 地址",-1)),t[6]||(t[6]=s("（用于与服务器通信），你可以",-1)),i(n,{href:"https://linuxhandbook.com/curl-command-examples/"},{default:e(()=>[...t[3]||(t[3]=[s("使用 curl 命令",-1)])]),_:1}),t[7]||(t[7]=s("。打开终端并输入以下命令：",-1))]),t[25]||(t[25]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curl ifconfig.me</span></span></code></pre></div><p>这应该只会返回你的 IP 地址而没有其他多余信息。我建议在分享这个地址时要小心，因为这相当于公布你的个人地址。</p><p><strong>注意：</strong> 如果 <code>curl</code> 没有安装，只需使用 <code>sudo apt install curl -y</code> 来解决问题，然后再试一次。</p><p>另一种可以查看公共 IP 地址的简单方法是在 Google 中搜索 “ip address”。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在本文中，我介绍了在 Uuntu Linux 中找到 IP 地址的不同方法，并向你概述了 IP 地址的用途以及它们对我们如此重要的原因。</p><p>我希望你喜欢这篇文章。如果你觉得文章有用，请在评论栏告诉我们！</p><hr>',8)),o("p",null,[t[9]||(t[9]=s("via: ",-1)),i(n,{href:"https://itsfoss.com/check-ip-address-ubuntu/"},{default:e(()=>[...t[8]||(t[8]=[s("https://itsfoss.com/check-ip-address-ubuntu/",-1)])]),_:1})]),o("p",null,[t[14]||(t[14]=s("作者：",-1)),i(n,{href:"https://itsfoss.com/author/sergiu/"},{default:e(()=>[...t[10]||(t[10]=[s("Sergiu",-1)])]),_:1}),t[15]||(t[15]=s(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[11]||(t[11]=[s("lujun9972",-1)])]),_:1}),t[16]||(t[16]=s(" 译者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...t[12]||(t[12]=[s("geekpi",-1)])]),_:1}),t[17]||(t[17]=s(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[13]||(t[13]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[20]||(t[20]=s("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[18]||(t[18]=[s("LCTT",-1)])]),_:1}),t[21]||(t[21]=s(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...t[19]||(t[19]=[s("Linux中国",-1)])]),_:1}),t[22]||(t[22]=s(" 荣誉推出",-1))])])}const C=r(d,[["render",g]]);export{T as __pageData,C as default};
